insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('37da3267-9a44-4710-9caf-f51a82091e6d', 'N5', 'Mệnh đề quan hệ（V thể thường + N）', 'Đây là N mà~ (vật mà~／nơi mà~／người mà~) — mệnh đề quan hệ bổ nghĩa cho danh từ', 'Động từ thể thường đứng trước danh từ để bổ nghĩa cho danh từ đó, giống mệnh đề quan hệ tiếng Việt "mà"', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 46, 'Mệnh đề quan hệ（V thể thường + N）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('fd25f09e-7c24-4b91-bdce-efe600004da5', 'N5', 'V thể thường + N を・が…（mệnh đề phụ trong câu）', 'Sử dụng mệnh đề động từ làm thành phần phụ (tân ngữ/chủ ngữ) trong câu', 'Mệnh đề quan hệ không chỉ đứng trước N làm chủ ngữ/tân ngữ của câu chính mà còn tự nó có thể mang を/が', '(mệnh đề: V thể thường + N) + を／が + V(câu chính)', 'Dùng cụm N đã được mệnh đề quan hệ bổ nghĩa làm tân ngữ hoặc chủ ngữ cho động từ chính của câu', NULL, NULL, NULL, '{"Mệnh đề quan hệ（V thể thường + N）"}', NULL, 46, 'V thể thường + N を・が…（mệnh đề phụ trong câu）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ffcd4bbd-5a1f-4dce-afad-31291b3af94a', 'N5', 'V thể thường + 時間・約束・用事・お金 がある・ない', 'Có／Không có thời gian, hẹn, việc, tiền để làm gì', 'Mệnh đề động từ bổ nghĩa cho 1 trong 4 danh từ: 時間/約束/用事/お金', 'V(thể thường) + 時間／約束／用事／お金 + が + あります／ありません', 'Diễn tả có hay không có đủ thời gian/lịch hẹn/việc/tiền để thực hiện 1 hành động', NULL, NULL, NULL, '{"Mệnh đề quan hệ（V thể thường + N）"}', NULL, 46, 'V thể thường + 時間・約束・用事・お金 がある・ない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('6635c635-b17e-4e7f-bcda-7dd96f59d94b', 'N5', 'Vる／Vた／Vない／Aい／Aな／N の + とき、～', 'Khi／Lúc ~ thì... (chỉ thời điểm xảy ra hành động/trạng thái vế sau)', 'Thì của động từ trước とき quyết định trình tự: る/ない = đồng thời hoặc trước; た = đã xảy ra ngay trước đó', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 46, 'Vる／Vた／Vない／Aい／Aな／N の + とき、～', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ab09cdb2-49bd-46eb-89bb-6c3f0a23090d', 'N5', 'V る + と', 'Hễ... thì sẽ... (chỉ sự thật hiển nhiên, quy luật tự nhiên)', 'と dùng cho sự thật luôn đúng/quy luật, không dùng để mời/rủ/ra lệnh ở vế sau', 'V(thể từ điển) + と、+ (kết quả tất yếu)', 'Diễn tả 1 quy luật/sự thật hiển nhiên: hễ điều kiện xảy ra thì kết quả luôn xảy ra theo', NULL, NULL, 'と không dùng được khi vế sau là câu mời/rủ/ra lệnh/ý chí cá nhân (khác với たら).', '{"Vたら／Aかったら／Aだったら／Nだったら"}', NULL, 47, 'V る + と', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f45c30bb-e64d-4891-8eb8-db1f89059776', 'N5', 'N（Địa điểm）を V（di chuyển）', 'Di chuyển qua／ngang qua N (địa điểm)', 'を ở đây không phải tân ngữ mà chỉ điểm đi qua của động từ di chuyển', 'N(địa điểm) + を + V(di chuyển: 歩く/散歩する/渡る...)', 'Chỉ địa điểm mà hành động di chuyển đi qua/ngang qua (không phải điểm đến)', NULL, NULL, 'Khác N+へ/に (điểm đến) — N+を chỉ đường đi/nơi đi qua, không phải đích đến.', '{}', NULL, 47, 'N（Địa điểm）を V（di chuyển）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d8e03326-cb7f-4b78-a5ea-df3dacd9a1d1', 'N5', 'V て + あげます／もらいます／くれます', 'Làm gì cho ai／Được ai làm gì cho／Ai đó làm gì cho mình', 'あげます=tôi làm cho người khác; もらいます=tôi được nhận từ ai; くれます=người khác làm cho tôi', NULL, NULL, NULL, NULL, NULL, '{"だれがくれましたか"}', NULL, 47, 'V て + あげます／もらいます／くれます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ab56745a-392b-4b37-9ab7-a535dee13c03', 'N5', 'V たら／（もし）A かったら／A だったら／N だったら、～', 'Nếu.../Giả sử... (điều kiện giả định) ； Sau khi.../Khi... (trình tự thời gian)', 'たら vừa dùng để giả định (nếu) vừa dùng để nói trình tự (sau khi/khi)', 'V(thể た, bỏ た/だ thêm たら/だら) ； Aい(bỏ い thêm かったら) ； Aな／N(thêm だったら)', NULL, NULL, NULL, NULL, '{"V る + と"}', NULL, 47, 'V たら／（もし）A かったら／A だったら／N だったら、～', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('3804a4e0-f248-45c0-b4dc-0ea4546f862d', 'N5', 'V て／（いくら）A くて／A なで／N で + も、～', 'Cho dù.../Mặc dù... (nhượng bộ, kết quả không như mong đợi/không thay đổi)', 'ても gắn vào thể て của động từ hoặc tính từ/danh từ để diễn tả nhượng bộ', 'V(thể て) + も ； Aい(bỏ い thêm くても) ； Aな／N(thêm でも)', 'Diễn tả 1 hành động/điều kiện xảy ra nhưng không dẫn đến kết quả mong đợi, hoặc kết quả không đổi dù có điều kiện đó', NULL, NULL, NULL, '{}', NULL, 47, 'V て／（いくら）A くて／A なで／N で + も、～', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('6d9dd17a-c0eb-4105-b232-24ce43d68732', '37da3267-9a44-4710-9caf-f51a82091e6d', 1, 'V thể thường + N(vật) — vật mà ai đó đã/đang làm gì', 'これは + V(thể thường) + N + です', 'Bổ nghĩa cho 1 danh từ chỉ đồ vật bằng 1 mệnh đề động từ đứng trước nó', NULL, 46, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('9fb752fe-1050-4d8f-9a67-63b9639f8189', '37da3267-9a44-4710-9caf-f51a82091e6d', 2, 'V thể thường + N(địa điểm) — nơi mà ai đó làm gì', 'ここ／そこ + は + V(thể thường) + 所（địa điểm）+ です', 'Bổ nghĩa cho 1 danh từ chỉ địa điểm bằng 1 mệnh đề động từ đứng trước nó', NULL, 46, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('e9a0fa65-6417-48aa-bb6a-83a671f7f949', '37da3267-9a44-4710-9caf-f51a82091e6d', 3, 'V thể thường + N(người) — người mà đang làm gì', 'A さん + は + V(thể thường) + 人 + です', 'Bổ nghĩa cho 1 danh từ chỉ người bằng 1 mệnh đề động từ đứng trước nó', NULL, 46, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('ffa657a6-d68e-4523-aefa-0a65a462abba', '6635c635-b17e-4e7f-bcda-7dd96f59d94b', 1, 'Vる／Vない／Aい／Aな／Nの + とき — hành động vế trước đồng thời hoặc chưa hoàn thành khi vế sau xảy ra', 'V(thể từ điển／ない)／Aい／Aな＋な／N＋の + とき、～', 'Chỉ thời điểm mà tại đó (chưa/đang) xảy ra 1 trạng thái, dùng thể hiện tại/tương lai của vế trước とき', NULL, 46, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('5061fe0d-12a0-4b56-98b4-95083c81f0ad', '6635c635-b17e-4e7f-bcda-7dd96f59d94b', 2, 'Vた + とき — hành động vế trước đã hoàn thành ngay trước khi vế sau xảy ra', 'V(thể た) + とき、～', 'Chỉ thời điểm ngay sau khi 1 hành động đã hoàn thành, thường dùng thuật lại quá khứ', NULL, 46, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('a7ac50fb-c713-4a7b-8fb1-5894e184b752', 'd8e03326-cb7f-4b78-a5ea-df3dacd9a1d1', 1, 'V てあげます — tôi (hoặc ai đó) làm 1 việc cho người khác', '（私は）N(người nhận) + に + V(thể て) + あげます', 'Chủ ngữ chủ động làm 1 việc tốt cho người khác', NULL, 47, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('4e06c2e9-7b62-4d73-ac07-28600cb1dee4', 'd8e03326-cb7f-4b78-a5ea-df3dacd9a1d1', 2, 'V てもらいます — tôi được nhận (việc gì) từ ai／nhờ ai làm giúp', '（私は）N(người làm) + に + V(thể て) + もらいます（いただきます）', 'Chủ ngữ nhận được lợi ích từ hành động của người khác (thường là được nhờ/được giúp)', NULL, 47, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('f1b89c0d-2395-43e0-868a-3724e51750a0', 'd8e03326-cb7f-4b78-a5ea-df3dacd9a1d1', 3, 'V てくれます — người khác chủ động làm 1 việc cho tôi (hoặc người thuộc phía tôi)', 'N(người làm) + が + V(thể て) + くれます（くださいます）', 'Người khác chủ động làm việc tốt cho chủ ngữ ẩn (tôi/gia đình tôi)', NULL, 47, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('e07d0a44-a9e6-424a-b507-b5fadd0d2dfd', 'ab56745a-392b-4b37-9ab7-a535dee13c03', 1, 'Điều kiện giả định: Nếu.../Giả sử...', 'V(thể たら)／Aかったら／Aだったら／Nだったら、～', 'Đưa ra giả định, kết quả ở vế sau chỉ xảy ra khi điều kiện giả định đó đúng', NULL, 47, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('17c68127-811f-4d62-933e-5b0beee953ac', 'ab56745a-392b-4b37-9ab7-a535dee13c03', 2, 'Trình tự thời gian: Sau khi.../Khi... (hành động chắc chắn sẽ xảy ra)', 'V(thể たら)、～', 'Chỉ thời điểm 1 hành động chắc chắn xảy ra rồi mới đến hành động ở vế sau (không mang tính giả định)', NULL, 47, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '6d9dd17a-c0eb-4105-b232-24ce43d68732', 1, 'standard', 'これはチャンさんが買ったかばんです。', 'Đây là cái túi mà chị Trang đã mua.', 'これはチャンさんが＿＿＿かばんです。', '買った', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '6d9dd17a-c0eb-4105-b232-24ce43d68732', 2, 'daily', 'これは私が作った料理です。', 'Đây là món ăn mà tôi đã nấu.', 'これは私が＿＿＿料理です。', '作った', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '6d9dd17a-c0eb-4105-b232-24ce43d68732', 3, 'daily', 'それは先生がくれた本です。', 'Đó là quyển sách mà thầy giáo đã tặng.', 'それは先生が＿＿＿本です。', 'くれた', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '9fb752fe-1050-4d8f-9a67-63b9639f8189', 1, 'standard', 'ここはたばこを吸う所です。', 'Đây là nơi hút thuốc lá.', 'ここは＿＿＿所です。', 'たばこを吸う', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '9fb752fe-1050-4d8f-9a67-63b9639f8189', 2, 'daily', 'そこは本を読む部屋です。', 'Đó là phòng đọc sách.', 'そこは＿＿＿部屋です。', '本を読む', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '9fb752fe-1050-4d8f-9a67-63b9639f8189', 3, 'daily', 'ここはコーヒーを飲む店です。', 'Đây là quán uống cà phê.', 'ここは＿＿＿店です。', 'コーヒーを飲む', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', 'e9a0fa65-6417-48aa-bb6a-83a671f7f949', 1, 'standard', 'Thaiさんは電話をかけている人です。', 'Anh Thái là người đang gọi điện thoại.', 'Thaiさんは＿＿＿人です。', '電話をかけている', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', 'e9a0fa65-6417-48aa-bb6a-83a671f7f949', 2, 'standard', 'あの眼鏡をかけている人は山田さんです。', 'Người đang đeo kính kia là anh Yamada.', 'あの＿＿＿人は山田さんです。', '眼鏡をかけている', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', 'e9a0fa65-6417-48aa-bb6a-83a671f7f949', 3, 'daily', 'あそこで歌っている人は誰ですか。', 'Người đang hát đằng kia là ai vậy?', 'あそこで＿＿＿人は誰ですか。', '歌っている', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type, review_status, corrected_text, correction_note) values ('fd25f09e-7c24-4b91-bdce-efe600004da5', NULL, 1, 'standard', '私が言葉を書いてください。', 'Hãy viết những từ mà tôi sẽ đọc nhé!', '私が＿＿＿を書いてください。', '言葉', 'pdf', 'needs_review', '私が言う（読む）言葉を書いてください。', 'Câu tiếng Nhật gốc thiếu động từ bổ nghĩa cho 言葉 (từ ngữ) — 私が言葉を書いてください nghĩa đen là "Tôi xin hãy viết từ" (vô lý vì đây là câu nhờ vả nhưng chủ ngữ lại là người nói). Bản dịch "những từ mà tôi sẽ đọc" cho thấy câu gốc cần thêm 言う hoặc 読む trước 言葉 mới đúng cấu trúc mệnh đề quan hệ, khả năng là lỗi thiếu chữ khi in ấn PDF gốc.');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fd25f09e-7c24-4b91-bdce-efe600004da5', NULL, 2, 'daily', '先生が話した内容をノートに書きます。', 'Tôi ghi vào vở nội dung mà thầy giáo đã nói.', '先生が話した＿＿＿をノートに書きます。', '内容', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fd25f09e-7c24-4b91-bdce-efe600004da5', NULL, 3, 'daily', '友達が薦めた映画を見ました。', 'Tôi đã xem bộ phim mà bạn tôi giới thiệu.', '友達が薦めた＿＿＿を見ました。', '映画', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ffcd4bbd-5a1f-4dce-afad-31291b3af94a', NULL, 1, 'standard', '私は中国語を勉強する時間がある。', 'Tôi có thời gian để học tiếng Trung Quốc.', '私は中国語を勉強する時間＿＿＿ある。', 'が', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ffcd4bbd-5a1f-4dce-afad-31291b3af94a', NULL, 2, 'standard', '私は寝る時間がありません。', 'Tôi không có thời gian để ngủ.', '私は寝る時間＿＿＿ありません。', 'が', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ffcd4bbd-5a1f-4dce-afad-31291b3af94a', NULL, 3, 'daily', '今日は友達と会う約束がある。', 'Hôm nay tôi có hẹn gặp bạn.', '今日は友達と会う約束＿＿＿ある。', 'が', 'generated');
