insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '6d9dd17a-c0eb-4105-b232-24ce43d68732', 'choose_meaning', 'Mẫu ngữ pháp nào có nghĩa: "V thể thường + N(vật) — vật mà ai đó đã/đang làm gì"?', 'V thể thường + 時間・約束・用事・お金 がある・ない', 'Mệnh đề quan hệ（V thể thường + N）', 'V thể thường + N を・が…（mệnh đề phụ trong câu）', 'Vる／Vた／Vない／Aい／Aな／N の + とき、～', 'Mệnh đề quan hệ（V thể thường + N）', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '6d9dd17a-c0eb-4105-b232-24ce43d68732', 'choose_connection', 'Cách nối đúng của mẫu "Mệnh đề quan hệ（V thể thường + N）" (V thể thường + N(vật) — vật mà ai đó đã/đang làm gì) là gì?', 'V(thể て) + も ； Aい(bỏ い thêm くても) ； Aな／N(thêm でも)', 'これは + V(thể thường) + N + です', '（私は）N(người làm) + に + V(thể て) + もらいます（いただきます）', 'V(thể た) + とき、～', 'これは + V(thể thường) + N + です', 'generated');
