insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('37da3267-9a44-4710-9caf-f51a82091e6d', '9fb752fe-1050-4d8f-9a67-63b9639f8189', 'choose_connection', 'Cách nối đúng của mẫu "Mệnh đề quan hệ（V thể thường + N）" (V thể thường + N(địa điểm) — nơi mà ai đó làm gì) là gì?', '（私は）N(người làm) + に + V(thể て) + もらいます（いただきます）', 'V(thể từ điển／ない)／Aい／Aな＋な／N＋の + とき、～', 'V(thể thường) + 時間／約束／用事／お金 + が + あります／ありません', 'ここ／そこ + は + V(thể thường) + 所（địa điểm）+ です', 'ここ／そこ + は + V(thể thường) + 所（địa điểm）+ です', 'generated');
